macro_rules! add_lifetime_parameters {
    () => {
        # [doc = " Make any implicit lifetime parameters explicit"] fn add_lifetime_parameters (sig : & mut Signature) { fn add_to_trait_object (generics : & mut Generics , var : & Pat , to : & mut TypeTraitObject) { let mut has_lifetime = false ; for bound in to . bounds . iter () { if let TypeParamBound :: Lifetime (_) = bound { has_lifetime = true ; } } if ! has_lifetime { let arg_ident = match * var { Pat :: Wild (_) => { compile_error (var . span () , "Mocked methods must have named arguments") ; format_ident ! ("dont_care") } , Pat :: Ident (ref pat_ident) => { if let Some (r) = & pat_ident . by_ref { compile_error (r . span () , "Mockall does not support by-reference argument bindings") ; } if let Some ((_at , subpat)) = & pat_ident . subpat { compile_error (subpat . span () , "Mockall does not support subpattern bindings") ; } pat_ident . ident . clone () } , _ => { compile_error (var . span () , "Unsupported argument type") ; format_ident ! ("dont_care") } } ; let s = format ! ("'__mockall_{arg_ident}") ; let span = Span :: call_site () ; let lt = Lifetime :: new (& s , span) ; to . bounds . push (TypeParamBound :: Lifetime (lt . clone ())) ; generics . lt_token . get_or_insert (Token ! [<] (span)) ; generics . gt_token . get_or_insert (Token ! [>] (span)) ; let gpl = GenericParam :: Lifetime (LifetimeParam :: new (lt)) ; generics . params . push (gpl) ; } } fn add_to_type (generics : & mut Generics , var : & Pat , ty : & mut Type) { match ty { Type :: Array (ta) => add_to_type (generics , var , ta . elem . as_mut ()) , Type :: BareFn (_) => () , Type :: ImplTrait (_) => () , Type :: Path (_) => () , Type :: Ptr (_) => () , Type :: Reference (tr) => { match tr . elem . as_mut () { Type :: Paren (tp) => { if let Type :: TraitObject (to) = tp . elem . as_mut () { add_to_trait_object (generics , var , to) ; } else { add_to_type (generics , var , tr . elem . as_mut ()) ; } } , Type :: TraitObject (to) => { add_to_trait_object (generics , var , to) ; * tr . elem = Type :: Paren (TypeParen { paren_token : token :: Paren :: default () , elem : Box :: new (Type :: TraitObject (to . clone ())) }) ; } , _ => add_to_type (generics , var , tr . elem . as_mut ()) , } } , Type :: Slice (ts) => add_to_type (generics , var , ts . elem . as_mut ()) , Type :: Tuple (tt) => { for ty in tt . elems . iter_mut () { add_to_type (generics , var , ty) } } , _ => compile_error (ty . span () , "unsupported type in this position") } } for arg in sig . inputs . iter_mut () { if let FnArg :: Typed (pt) = arg { add_to_type (& mut sig . generics , & pt . pat , & mut pt . ty) } } }
    };
}

add_lifetime_parameters!()